import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
import java.util.stream.Collectors;

public class SalesAnalytics {

    private static double round2(double value) {
        return Math.round(value * 100.0) / 100.0;
    }

    public static double revenueIn(List<SalesOrder> orders, String region) {
        double total = orders.stream()
                .filter(order -> order.getRegion().equals(region))
                .mapToDouble(SalesOrder::total)
                .sum();
        return round2(total);
    }

    public static Map<String, Double> revenuePerCategory(List<SalesOrder> orders) {
        Map<String, Double> raw = orders.stream()
                .flatMap(order -> order.getLines().stream())
                .collect(Collectors.groupingBy(OrderLine::getCategory,
                        TreeMap::new,
                        Collectors.summingDouble(OrderLine::lineTotal)));
        Map<String, Double> rounded = new TreeMap<>();
        for (Map.Entry<String, Double> entry : raw.entrySet()) {
            rounded.put(entry.getKey(), round2(entry.getValue()));
        }
        return rounded;
    }

    public static List<String> topCustomers(List<SalesOrder> orders, int n) {
        Map<String, Double> spend = orders.stream()
                .collect(Collectors.groupingBy(SalesOrder::getCustomer,
                        Collectors.summingDouble(SalesOrder::total)));
        return spend.entrySet().stream()
                .sorted(Map.Entry.<String, Double>comparingByValue(Comparator.reverseOrder())
                        .thenComparing(Map.Entry.comparingByKey()))
                .limit(Math.max(n, 0))
                .map(Map.Entry::getKey)
                .collect(Collectors.toList());
    }

    public static Optional<SalesOrder> largestOrder(List<SalesOrder> orders) {
        return orders.stream().max(Comparator.comparingDouble(SalesOrder::total));
    }

    public static long distinctProducts(List<SalesOrder> orders) {
        return orders.stream()
                .flatMap(order -> order.getLines().stream())
                .map(OrderLine::getProduct)
                .distinct()
                .count();
    }
}

