import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.Optional;

public class SalesAnalyticsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static List<SalesOrder> fixture() {
        List<SalesOrder> orders = new ArrayList<>();
        orders.add(new SalesOrder("o1", "ana", "north", Arrays.asList(
                new OrderLine("mug", "kitchen", 2, 5.0),
                new OrderLine("pan", "kitchen", 1, 20.0))));
        orders.add(new SalesOrder("o2", "bo", "south", Arrays.asList(
                new OrderLine("lamp", "home", 1, 12.5))));
        orders.add(new SalesOrder("o3", "ana", "north", Arrays.asList(
                new OrderLine("mug", "kitchen", 4, 5.0),
                new OrderLine("rug", "home", 1, 40.0))));
        orders.add(new SalesOrder("o4", "cy", "south", Arrays.asList(
                new OrderLine("lamp", "home", 2, 12.5),
                new OrderLine("pan", "kitchen", 1, 20.0))));
        return orders;
    }

    static String orderId(Optional<SalesOrder> order) {
        return order == null ? "null optional"
                             : order.map(SalesOrder::getId).orElse("empty");
    }

    public static void main(String[] args) {
        List<SalesOrder> orders = fixture();

        check("revenue in the north", 90.0, SalesAnalytics.revenueIn(orders, "north"));
        check("revenue in the south", 57.5, SalesAnalytics.revenueIn(orders, "south"));
        check("revenue in an unknown region", 0.0, SalesAnalytics.revenueIn(orders, "west"));

        Map<String, Double> perCategory = SalesAnalytics.revenuePerCategory(orders);
        check("category count", 2, perCategory.size());
        check("kitchen revenue", Double.valueOf(70.0), perCategory.get("kitchen"));
        check("home revenue", Double.valueOf(77.5), perCategory.get("home"));
        check("categories are sorted", "[home, kitchen]",
              String.valueOf(new ArrayList<>(perCategory.keySet())));

        check("top two customers", "[ana, cy]",
              String.valueOf(SalesAnalytics.topCustomers(orders, 2)));
        check("all customers ranked", "[ana, cy, bo]",
              String.valueOf(SalesAnalytics.topCustomers(orders, 10)));
        check("top zero customers", "[]",
              String.valueOf(SalesAnalytics.topCustomers(orders, 0)));

        check("largest order", "o3", orderId(SalesAnalytics.largestOrder(orders)));
        check("largest order of nothing", "empty",
              orderId(SalesAnalytics.largestOrder(new ArrayList<SalesOrder>())));
        check("distinct products", 4L, SalesAnalytics.distinctProducts(orders));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

